using System;
using System.Globalization;

internal static class Program
{
    private const double SolarMass = 4.0 * Math.PI * Math.PI;
    private const double DaysPerYear = 365.24;
    private const double Dt = 1e-2;

    private static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);

        // Bodies: 0 = Sun, 1 = Jupiter, 2 = Saturn, 3 = Uranus, 4 = Neptune
        double[] x = new double[5];
        double[] y = new double[5];
        double[] z = new double[5];
        double[] vx = new double[5];
        double[] vy = new double[5];
        double[] vz = new double[5];
        double[] m = new double[5];

        // Sun
        m[0] = SolarMass;

        // Jupiter
        x[1] = 4.84143144246472090e+00;
        y[1] = -1.16032004402742839e+00;
        z[1] = -1.03622044471123109e-01;
        vx[1] = 1.66007664209528561e-03 * DaysPerYear;
        vy[1] = 7.69901118419740425e-03 * DaysPerYear;
        vz[1] = -6.90460016972063023e-05 * DaysPerYear;
        m[1] = 9.54791938424326609e-04 * SolarMass;

        // Saturn
        x[2] = 8.34336671824457987e+00;
        y[2] = 4.12479856414230455e+00;
        z[2] = -4.03523417114321381e-01;
        vx[2] = -2.76742510726862411e-03 * DaysPerYear;
        vy[2] = 4.99852801234917238e-03 * DaysPerYear;
        vz[2] = 2.30417296837568739e-05 * DaysPerYear;
        m[2] = 2.85885980666130812e-04 * SolarMass;

        // Uranus
        x[3] = 1.28943695621391310e+01;
        y[3] = -1.51111514016986312e+01;
        z[3] = -2.23307578892655734e-01;
        vx[3] = 2.96460137564763199e-03 * DaysPerYear;
        vy[3] = 2.37847173959480950e-03 * DaysPerYear;
        vz[3] = -2.96589568540237556e-05 * DaysPerYear;
        m[3] = 4.36624404335162998e-05 * SolarMass;

        // Neptune
        x[4] = 1.53796971148509165e+01;
        y[4] = -2.59193146099879641e+01;
        z[4] = 1.79284863061560182e-01;
        vx[4] = 2.68067772490389322e-03 * DaysPerYear;
        vy[4] = -1.62813115592709249e-03 * DaysPerYear;
        vz[4] = -3.43504920362242147e-05 * DaysPerYear;
        m[4] = 5.15138902046611451e-05 * SolarMass;

        // Offset momentum: Sun absorbs the system's total momentum.
        double px = 0.0, py = 0.0, pz = 0.0;
        for (int i = 0; i < 5; i++)
        {
            px += vx[i] * m[i];
            py += vy[i] * m[i];
            pz += vz[i] * m[i];
        }
        vx[0] = -px / SolarMass;
        vy[0] = -py / SolarMass;
        vz[0] = -pz / SolarMass;

        var inv = CultureInfo.InvariantCulture;
        Console.WriteLine(Energy(x, y, z, vx, vy, vz, m).ToString("F9", inv));

        for (int step = 0; step < n; step++)
            Advance(x, y, z, vx, vy, vz, m);

        Console.WriteLine(Energy(x, y, z, vx, vy, vz, m).ToString("F9", inv));
    }

    // Fully unrolled symplectic step for the fixed 5-body system.
    // Operation order matches the reference implementation bit-for-bit.
    private static void Advance(double[] x, double[] y, double[] z,
                                double[] vx, double[] vy, double[] vz, double[] m)
