        double x0 = x[0], y0 = y[0], z0 = z[0];
        double x1 = x[1], y1 = y[1], z1 = z[1];
        double x2 = x[2], y2 = y[2], z2 = z[2];
        double x3 = x[3], y3 = y[3], z3 = z[3];
        double x4 = x[4], y4 = y[4], z4 = z[4];

        double v0x = vx[0], v0y = vy[0], v0z = vz[0];
        double v1x = vx[1], v1y = vy[1], v1z = vz[1];
        double v2x = vx[2], v2y = vy[2], v2z = vz[2];
        double v3x = vx[3], v3y = vy[3], v3z = vz[3];
        double v4x = vx[4], v4y = vy[4], v4z = vz[4];

        double m0 = m[0], m1 = m[1], m2 = m[2], m3 = m[3], m4 = m[4];

        double dx, dy, dz, d2, mag;

        // Pair (0,1)
        dx = x0 - x1; dy = y0 - y1; dz = z0 - z1;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v0x -= dx * m1 * mag; v0y -= dy * m1 * mag; v0z -= dz * m1 * mag;
        v1x += dx * m0 * mag; v1y += dy * m0 * mag; v1z += dz * m0 * mag;

        // Pair (0,2)
        dx = x0 - x2; dy = y0 - y2; dz = z0 - z2;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v0x -= dx * m2 * mag; v0y -= dy * m2 * mag; v0z -= dz * m2 * mag;
        v2x += dx * m0 * mag; v2y += dy * m0 * mag; v2z += dz * m0 * mag;

        // Pair (0,3)
        dx = x0 - x3; dy = y0 - y3; dz = z0 - z3;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v0x -= dx * m3 * mag; v0y -= dy * m3 * mag; v0z -= dz * m3 * mag;
        v3x += dx * m0 * mag; v3y += dy * m0 * mag; v3z += dz * m0 * mag;

        // Pair (0,4)
        dx = x0 - x4; dy = y0 - y4; dz = z0 - z4;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v0x -= dx * m4 * mag; v0y -= dy * m4 * mag; v0z -= dz * m4 * mag;
        v4x += dx * m0 * mag; v4y += dy * m0 * mag; v4z += dz * m0 * mag;

        // Pair (1,2)
        dx = x1 - x2; dy = y1 - y2; dz = z1 - z2;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v1x -= dx * m2 * mag; v1y -= dy * m2 * mag; v1z -= dz * m2 * mag;
        v2x += dx * m1 * mag; v2y += dy * m1 * mag; v2z += dz * m1 * mag;

        // Pair (1,3)
        dx = x1 - x3; dy = y1 - y3; dz = z1 - z3;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v1x -= dx * m3 * mag; v1y -= dy * m3 * mag; v1z -= dz * m3 * mag;
        v3x += dx * m1 * mag; v3y += dy * m1 * mag; v3z += dz * m1 * mag;

        // Pair (1,4)
        dx = x1 - x4; dy = y1 - y4; dz = z1 - z4;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v1x -= dx * m4 * mag; v1y -= dy * m4 * mag; v1z -= dz * m4 * mag;
        v4x += dx * m1 * mag; v4y += dy * m1 * mag; v4z += dz * m1 * mag;

        // Pair (2,3)
        dx = x2 - x3; dy = y2 - y3; dz = z2 - z3;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v2x -= dx * m3 * mag; v2y -= dy * m3 * mag; v2z -= dz * m3 * mag;
        v3x += dx * m2 * mag; v3y += dy * m2 * mag; v3z += dz * m2 * mag;

        // Pair (2,4)
        dx = x2 - x4; dy = y2 - y4; dz = z2 - z4;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v2x -= dx * m4 * mag; v2y -= dy * m4 * mag; v2z -= dz * m4 * mag;
        v4x += dx * m2 * mag; v4y += dy * m2 * mag; v4z += dz * m2 * mag;

        // Pair (3,4)
        dx = x3 - x4; dy = y3 - y4; dz = z3 - z4;
        d2 = dx * dx + dy * dy + dz * dz;
        mag = Dt / (d2 * Math.Sqrt(d2));
        v3x -= dx * m4 * mag; v3y -= dy * m4 * mag; v3z -= dz * m4 * mag;
        v4x += dx * m3 * mag; v4y += dy * m3 * mag; v4z += dz * m3 * mag;

        // Store updated velocities.
        vx[0] = v0x; vy[0] = v0y; vz[0] = v0z;
        vx[1] = v1x; vy[1] = v1y; vz[1] = v1z;
        vx[2] = v2x; vy[2] = v2y; vz[2] = v2z;
        vx[3] = v3x; vy[3] = v3y; vz[3] = v3z;
        vx[4] = v4x; vy[4] = v4y; vz[4] = v4z;

        // Drift: positions advance with the new velocities.
        x[0] = x0 + Dt * v0x; y[0] = y0 + Dt * v0y; z[0] = z0 + Dt * v0z;
        x[1] = x1 + Dt * v1x; y[1] = y1 + Dt * v1y; z[1] = z1 + Dt * v1z;
        x[2] = x2 + Dt * v2x; y[2] = y2 + Dt * v2y; z[2] = z2 + Dt * v2z;
        x[3] = x3 + Dt * v3x; y[3] = y3 + Dt * v3y; z[3] = z3 + Dt * v3z;
        x[4] = x4 + Dt * v4x; y[4] = y4 + Dt * v4y; z[4] = z4 + Dt * v4z;
    }

    private static double Energy(double[] x, double[] y, double[] z,
                                 double[] vx, double[] vy, double[] vz, double[] m)
    {
        double e = 0.0;
        for (int i = 0; i < 5; i++)
        {
            double mi = m[i];
            double vxi = vx[i], vyi = vy[i], vzi = vz[i];
            e += 0.5 * mi * (vxi * vxi + vyi * vyi + vzi * vzi);
            for (int j = i + 1; j < 5; j++)
            {
                double dx = x[i] - x[j];
                double dy = y[i] - y[j];
                double dz = z[i] - z[j];
                double dist = Math.Sqrt(dx * dx + dy * dy + dz * dz);
                e -= (mi * m[j]) / dist;
            }
        }
        return e;
    }
}
