            b->velocity.y -= dy * b2->mass * mag;
            b->velocity.z -= dz * b2->mass * mag;
            b2->velocity.x += dx * b->mass * mag;
            b2->velocity.y += dy * b->mass * mag;
            b2->velocity.z += dz * b->mass * mag;
