using System;
using System.Text;

internal sealed class TreeNode
{
    private TreeNode Left;
    private TreeNode Right;

    private TreeNode() { }

    internal static TreeNode MakeTree(int depth)
    {
        return depth == 0 ? null : new TreeNode(depth);
    }

    private TreeNode(int depth)
    {
        if (depth > 1)
        {
            Left = MakeTree(depth - 1);
            Right = MakeTree(depth - 1);
        }
    }

    internal int Check()
    {
        int sum = 1;
        if (Left != null) sum += Left.Check();
        if (Right != null) sum += Right.Check();
        return sum;
    }
}

internal static class Program
{
    private static void Main(string[] args)
    {
        int n = int.Parse(args[0]);

        var sb = new StringBuilder();

        // Stretch tree
        int stretchDepth = n + 1;
        TreeNode stretchTree = TreeNode.MakeTree(stretchDepth);
        sb.Append("stretch tree of depth ").Append(stretchDepth)
          .Append("\t check: ").Append(stretchTree.Check()).Append('\n');
        stretchTree = null;

        // Long-lived tree
        TreeNode longLivedTree = TreeNode.MakeTree(n);

        for (int d = 4; d <= n; d += 2)
        {
            int iterations = 1 << (n - d + 4);
            int sum = 0;
            for (int i = 0; i < iterations; i++)
            {
                TreeNode t = TreeNode.MakeTree(d);
                sum += t.Check();
            }
            sb.Append(iterations).Append("\t trees of depth ").Append(d)
              .Append("\t check: ").Append(sum).Append('\n');
        }

        sb.Append("long lived tree of depth ").Append(n)
          .Append("\t check: ").Append(longLivedTree.Check()).Append('\n');

        Console.Write(sb.ToString());
    }
}
```

