```csharp
using System;
using System.Text;

internal sealed class TreeNode
{
    public TreeNode Left;
    public TreeNode Right;
}

internal static class Program
{
    private static TreeNode MakeTree(int depth)
    {
        if (depth <= 0)
        {
            return null;
        }

        TreeNode node = new TreeNode();
        if (depth > 1)
        {
            node.Left = MakeTree(depth - 1);
            node.Right = MakeTree(depth - 1);
        }
        return node;
    }

    private static long Check(TreeNode node)
    {
        if (node == null)
        {
            return 0;
        }

        long sum = 1;
        if (node.Left != null)
        {
            sum += Check(node.Left);
        }
        if (node.Right != null)
        {
            sum += Check(node.Right);
        }
        return sum;
    }

    private static int Main(string[] args)
    {
        int n = int.Parse(args[0].Trim());

        StringBuilder sb = new StringBuilder(1024);

        // Stretch tree of depth n + 1; check, print, then discard it.
        int stretchDepth = n + 1;
        TreeNode stretchTree = MakeTree(stretchDepth);
        sb.Append("stretch tree of depth ").Append(stretchDepth)
          .Append("\t check: ").Append(Check(stretchTree)).Append('\n');
        stretchTree = null;

        // Long-lived tree of depth n; kept alive while the short-lived
        // trees below are allocated and collected.
        TreeNode longLivedTree = MakeTree(n);

        for (int d = 4; d <= n; d += 2)
        {
            int iterations = 1 << (n - d + 4);
            long sum = 0;
            for (int i = 0; i < iterations; i++)
            {
                sum += Check(MakeTree(d));
            }
            sb.Append(iterations).Append("\t trees of depth ").Append(d)
              .Append("\t check: ").Append(sum).Append('\n');
        }

        sb.Append("long lived tree of depth ").Append(n)
          .Append("\t check: ").Append(Check(longLivedTree)).Append('\n');

        Console.Write(sb.ToString());
        return 0;
    }
}
```

