```csharp
// binary-trees benchmark
// Build a "stretch" tree of depth N+1, a long-lived tree of depth N, and for
// each even depth d in [4, N] build 2^(N-d+4) short-lived trees of depth d,
// printing node-count checksums for each group.
//
// Invocation: <prog> N

using System;
using System.Text;

internal sealed class TreeNode
{
    public TreeNode Left;
    public TreeNode Right;
}

internal static class Program
{
    // Build a full binary tree of the given depth (depth 0 -> empty tree).
    private static TreeNode MakeTree(int depth)
    {
        if (depth <= 0)
        {
            return null;
        }

        TreeNode node = new TreeNode();
        if (depth > 1)
        {
            node.Left = MakeTree(depth - 1);
            node.Right = MakeTree(depth - 1);
        }
        return node;
    }

    // Count nodes: 1 + check(left) + check(right); 0 for an empty tree.
    private static int Check(TreeNode node)
    {
        if (node == null)
        {
            return 0;
        }

        int count = 1;
        if (node.Left != null)
        {
            count += Check(node.Left);
        }
        if (node.Right != null)
        {
            count += Check(node.Right);
        }
        return count;
    }

    private static void Main(string[] args)
    {
        int n = int.Parse(args[0].Trim());

        var outBuf = new StringBuilder(512);

        // 1) Stretch tree of depth N+1: check it, print, then drop it so the
        //    GC can reclaim it while the rest of the workload runs.
        int stretchDepth = n + 1;
        TreeNode stretchTree = MakeTree(stretchDepth);
        outBuf.Append("stretch tree of depth ").Append(stretchDepth)
              .Append("\t check: ").Append(Check(stretchTree)).Append('\n');
        stretchTree = null;

        // 2) Long-lived tree of depth N: stays reachable throughout the
        //    short-lived allocation storm below.
        TreeNode longLivedTree = MakeTree(n);

        // 3) Short-lived trees: for each even depth d = 4, 6, ..., N build
        //    2^(N-d+4) trees of depth d and sum their checks.
        for (int d = 4; d <= n; d += 2)
        {
            int iterations = 1 << (n - d + 4);
            long checkSum = 0;
            for (int i = 0; i < iterations; i++)
            {
                checkSum += Check(MakeTree(d));
            }
            outBuf.Append(iterations).Append("\t trees of depth ").Append(d)
                  .Append("\t check: ").Append(checkSum).Append('\n');
        }

        // 4) Finally check the long-lived tree.
        outBuf.Append("long lived tree of depth ").Append(n)
              .Append("\t check: ").Append(Check(longLivedTree)).Append('\n');

        Console.Write(outBuf.ToString());
    }
}
```

