        WriteHeader(">ONE Homo sapiens alu");
        WriteRepeatFasta(alu, 2L * n);

        WriteHeader(">TWO IUB ambiguity codes");
        WriteRandomFasta(iubTable, 3L * n);

        WriteHeader(">THREE Homo sapiens frequency");
        WriteRandomFasta(hsTable, 5L * n);

        Flush();
        _stdout.Flush();
    }

    // Precomputes, for every possible raw seed value k in [0, IM), the symbol
    // selected for draw value r = k / IM, i.e. the first symbol whose
    // cumulative probability (accumulated in order, in double precision) is
    // strictly greater than r. Exactly equivalent to searching per draw.
    private static byte[] BuildLookupTable(char[] symbols, double[] probs)
    {
        int m = symbols.Length;
        double[] cp = new double[m];
        double acc = 0.0;
        for (int i = 0; i < m; i++)
        {
            acc += probs[i];
            cp[i] = acc;
        }

        byte[] table = new byte[IM];
        for (int k = 0; k < IM; k++)
        {
            double r = (double)k / IM;
            int j = 0;
            while (j < m - 1 && cp[j] <= r) j++;
            table[k] = (byte)symbols[j];
        }
        return table;
    }

    private static void WriteHeader(string header)
    {
        if (_pos + header.Length + 1 > _buf.Length) Flush();
        for (int i = 0; i < header.Length; i++) _buf[_pos++] = (byte)header[i];
