        if (outPos + bytes.Length > outBuf.Length) Flush();
        // bytes.Length is small (headers), so this is fine
        Buffer.BlockCopy(bytes, 0, outBuf, outPos, bytes.Length);
        outPos += bytes.Length;
    }

    static void WriteAscii(string s)
    {
        // headers are ASCII
        ...
    }

    static void Main(string[] args)
    {
        int n = int.Parse(args[0].Trim());
