    private static byte[] BuildTable(char[] chars, double[] probs)
    {
        int m = chars.Length;
        double[] cp = new double[m];
        double acc = 0.0;
        for (int i = 0; i < m; i++)
        {
            acc += probs[i];
            cp[i] = acc;
        }

        byte[] table = new byte[IM];
        for (int k = 0; k < IM; k++)
        {
            double r = (double)k / IM;
            int j = 0;
            while (j < m - 1 && cp[j] <= r) j++;
            table[k] = (byte)chars[j];
        }
        return table;
    }

    private static void WriteHeader(string s)
    {
        int len = s.Length;
        if (_pos + len + 1 > _buf.Length) Flush();
        for (int i = 0; i < len; i++) _buf[_pos++] = (byte)s[i];
        _buf[_pos++] = (byte)'\n';
    }

    private static void WriteRepeatFasta(byte[] alu, int total)
    {
        int aluLen = alu.Length;
        int aluPos = 0;
        int remaining = total;
        while (remaining > 0)
        {
            int chunk = remaining < 60 ? remaining : 60;
            if (_pos + chunk + 1 > _buf.Length) Flush();
            for (int i = 0; i < chunk; i++)
            {
                _buf[_pos++] = alu[aluPos++];
                if (aluPos == aluLen) aluPos = 0;
            }
            _buf[_pos++] = (byte)'\n';
            remaining -= chunk;
        }
    }

    private static void WriteRandomFasta(byte[] table, int total)
    {
        int remaining = total;
        while (remaining > 0)
        {
            int chunk = remaining < 60 ? remaining : 60;
            if (_pos + chunk + 1 > _buf.Length) Flush();
            for (int i = 0; i < chunk; i++)
            {
                _seed = (_seed * IA + IC) % IM;
                _buf[_pos++] = table[_seed];
            }
            _buf[_pos++] = (byte)'\n';
            remaining -= chunk;
        }
    }

    private static void Flush()
    {
        if (_pos > 0)
        {
            _out.Write(_buf, 0, _pos);
            _pos = 0;
        }
    }
