```csharp
using System;
using System.IO;

internal static class Program
{
    // Linear congruential generator constants (Benchmarks Game "fasta").
    private const int IM = 139968;
    private const int IA = 3877;
    private const int IC = 29573;

    private const int LineLen = 60;
    private const int BufSize = 1 << 16;

    private static int _seed = 42;

    private static Stream _stdout;
    private static readonly byte[] _buf = new byte[BufSize];
    private static int _pos;

    private static void Main(string[] args)
    {
        long n = long.Parse(args[0].Trim());
        _stdout = Console.OpenStandardOutput();

        // IUB ambiguity code table (order matters).
        byte[] iubTable = BuildLookupTable(
            new[] { 'a', 'c', 'g', 't', 'B', 'D', 'H', 'K', 'M', 'N', 'R', 'S', 'V', 'W', 'Y' },
            new[] { 0.27, 0.12, 0.12, 0.27,
                    0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
                    0.02, 0.02, 0.02, 0.02, 0.02 });

        // Homo sapiens frequency table.
        byte[] hsTable = BuildLookupTable(
            new[] { 'a', 'c', 'g', 't' },
            new[] { 0.3029549426680, 0.1979883004921,
                    0.1975473066391, 0.3015094502008 });

        // ALU 287-character sequence.
        const string Alu =
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
            "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
            "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
            "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
            "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";
        var alu = new byte[Alu.Length];
        for (int i = 0; i < Alu.Length; i++) alu[i] = (byte)Alu[i];

        WriteHeader(">ONE Homo sapiens alu");
        WriteRepeatFasta(alu, 2L * n);

        WriteHeader(">TWO IUB ambiguity codes");
        WriteRandomFasta(iubTable, 3L * n);

        WriteHeader(">THREE Homo sapiens frequency");
        WriteRandomFasta(hsTable, 5L * n);

        Flush();
    }

    // Precomputes, for every possible raw seed value k in [0, IM),
    // the symbol selected for draw value r = k / IM, i.e. the first
    // symbol whose cumulative probability is strictly greater than r.
    private static byte[] BuildLookupTable(char[] symbols, double[] probs)
    {
        int m = symbols.Length;
        var cp = new double[m];
        double acc = 0.0;
        for (int i = 0; i < m; i++)
        {
            acc += probs[i];
            cp[i] = acc;
        }

        var table = new byte[IM];
        for (int k = 0; k < IM; k++)
        {
            double r = (double)k / IM;
            int j = 0;
            while (j < m - 1 && cp[j] <= r) j++;
            table[k] = (byte)symbols[j];
        }
        return table;
    }

    private static void WriteHeader(string header)
    {
        if (_pos + header.Length + 1 > _buf.Length) Flush();
        for (int i = 0; i < header.Length; i++) _buf[_pos++] = (byte)header[i];
        _buf[_pos++] = (byte)'\n';
    }

    private static void WriteRepeatFasta(byte[] alu, long total)
    {
        byte[] buf = _buf;
        int pos = _pos;
        int aluLen = alu.Length;
        int aluPos = 0;
        long remaining = total;

        while (remaining > 0)
        {
            if (pos + LineLen + 1 > buf.Length)
            {
                _pos = pos;
                Flush();
                pos = 0;
            }

            int chunk = remaining < LineLen ? (int)remaining : LineLen;
            for (int i = 0; i < chunk; i++)
            {
                buf[pos++] = alu[aluPos++];
                if (aluPos == aluLen) aluPos = 0;
            }
            buf[pos++] = (byte)'\n';
            remaining -= chunk;
        }

        _pos = pos;
    }

    private static void WriteRandomFasta(byte[] table, long total)
    {
        byte[] buf = _buf;
        int pos = _pos;
        int seed = _seed;
        long remaining = total;

        while (remaining > 0)
        {
            if (pos + LineLen + 1 > buf.Length)
            {
                _pos = pos;
                Flush();
                pos = 0;
            }

            int chunk = remaining < LineLen ? (int)remaining : LineLen;
            for (int i = 0; i < chunk; i++)
            {
                seed = (seed * IA + IC) % IM;
                buf[pos++] = table[seed];
            }
            buf[pos++] = (byte)'\n';
            remaining -= chunk;
        }

        _pos = pos;
        _seed = seed;
    }

    private static void Flush()
    {
        if (_pos > 0)
        {
            _stdout.Write(_buf, 0, _pos);
            _pos = 0;
        }
    }
}
