    // compacts it in place into data[0..seqLen). Falls back to the whole input when the
    // header is absent (raw sequence piped directly).
    private static int ExtractThreeSequence(byte[] data)
    {
        int header = FindThreeHeader(data);
        int start;
        int end;
        if (header >= 0)
        {
            int i = header;
            while (i < data.Length && data[i] != (byte)'\n' && data[i] != (byte)'\r')
            {
                i++;
            }
            if (i < data.Length)
            {
                if (data[i] == (byte)'\r' && i + 1 < data.Length && data[i + 1] == (byte)'\n')
                {
                    i++;
                }
                start = i + 1;
            }
            else
            {
                start = data.Length;
            }
            end = IndexOfByte(data, (byte)'>', start); // next FASTA record, if any
            if (end < 0)
            {
                end = data.Length;
            }
        }
        else
        {
            start = 0;
            end = data.Length;
        }

        int write = 0;
        int read = start;
        while (read < end)
        {
            byte b = data[read];
            if (b <= 32)
            {
                read++;
                continue;
            }
            if (b == (byte)'>')
            {
                while (read < end && data[read] != (byte)'\n' && data[read] != (byte)'\r')
                {
                    read++;
                }
                continue;
            }
            if (b >= (byte)'a' && b <= (byte)'z')
            {
                b = (byte)(b - 32);
            }
            data[write++] = b;
            read++;
        }
        return write;
    }

    private static int FindThreeHeader(byte[] data)
    {
        int pos = 0;
        while (true)
        {
            int gt = IndexOfByte(data, (byte)'>', pos);
            if (gt < 0)
            {
                return -1;
            }
            if (gt + 6 <= data.Length
                && data[gt + 1] == (byte)'T'
                && data[gt + 2] == (byte)'H'
                && data[gt + 3] == (byte)'R'
                && data[gt + 4] == (byte)'E'
                && data[gt + 5] == (byte)'E')
            {
                return gt;
            }
            pos = gt + 1;
        }
    }

    private static int IndexOfByte(byte[] data, byte value, int start)
    {
        for (int i = start; i < data.Length; i++)
        {
            if (data[i] == value)
            {
                return i;
            }
        }
        return -1;
    }
}
