Looking at this problem:

- It's the classic FASTA reverse-complement task: read records (header line starting with `>` + wrapped sequence lines), output the header verbatim and the reverse-complemented sequence.
- "Preserving line-wrapping" for a *reversed* sequence means the wrapping mirrors: the input's last chunk becomes the output's short first line, etc. This is exactly what both natural implementations produce — reversing the list of lines and each line, or reversing the whole sequence block in place including its interior newlines (the canonical fast trick for this benchmark).
- Strategy: slurp all of stdin into one byte buffer, find record starts (`>` at line start), then for each record reverse+complement the sequence block **in place** (excluding the trailing line break, which stays put). Since the transformation is in place, headers and newlines are preserved automatically, and the finished buffer is written to stdout in one call.
- Complement table: A↔T, C↔G, U→A, R↔Y, K↔M, B↔V, D↔H, S/W/N fixed; every other byte (notably `\n`) maps to itself. Lowercase handled too. `N` from argv is parsed but unused (data comes entirely from stdin).

I verified the logic on multi-line and short-last-line examples (e.g. input lines `[6,5]` → output lines `[5,6]`), empty sequences, missing trailing newline, and multiple records.

```csharp
using System;
using System.Collections.Generic;
using System.IO;

internal static class Program
{
    private static void Main(string[] args)
    {
        // Harness contract: the program is invoked as "<program> N".  N has no
        // effect on this task (all data arrives on stdin), but the first
        // argument is parsed as an integer, as the contract requires.
        if (args != null && args.Length > 0)
        {
            int n;
            int.TryParse(args[0], out n);
        }

        // IUPAC complement table.  Every byte that is not an IUPAC code --
        // in particular '\n' -- maps to itself, so line breaks (and any
        // unexpected character) pass through the transformation untouched.
        byte[] comp = new byte[256];
        for (int i = 0; i < 256; i++) comp[i] = (byte)i;

        comp['A'] = (byte)'T'; comp['T'] = (byte)'A';
        comp['C'] = (byte)'G'; comp['G'] = (byte)'C';
        comp['U'] = (byte)'A';
        comp['R'] = (byte)'Y'; comp['Y'] = (byte)'R';
        comp['K'] = (byte)'M'; comp['M'] = (byte)'K';
        comp['B'] = (byte)'V'; comp['V'] = (byte)'B';
        comp['D'] = (byte)'H'; comp['H'] = (byte)'D';
        comp['S'] = (byte)'S'; comp['W'] = (byte)'W'; comp['N'] = (byte)'N';

        comp['a'] = (byte)'t'; comp['t'] = (byte)'a';
        comp['c'] = (byte)'g'; comp['g'] = (byte)'c';
        comp['u'] = (byte)'a';
        comp['r'] = (byte)'y'; comp['y'] = (byte)'r';
        comp['k'] = (byte)'m'; comp['m'] = (byte)'k';
        comp['b'] = (byte)'v'; comp['v'] = (byte)'b';
        comp['d'] = (byte)'h'; comp['h'] = (byte)'d';
        comp['s'] = (byte)'s'; comp['w'] = (byte)'w'; comp['n'] = (byte)'n';

        // Slurp all of stdin, dropping carriage returns so that the line
        // handling below is uniform.
        Stream inp = Console.OpenStandardInput();
        MemoryStream ms = new MemoryStream(1 << 20);
        byte[] buf = new byte[1 << 16];
        int got;
        while ((got = inp.Read(buf, 0, buf.Length)) > 0)
        {
            int w = 0;
            for (int i = 0; i < got; i++)
                if (buf[i] != 13)
                    buf[w++] = buf[i];
            ms.Write(buf, 0, w);
        }

        byte[] data = ms.GetBuffer();
        int len = (int)ms.Length;

        // Locate the start of every record: a '>' that begins a line.
        List<int> starts = new List<int>();
        for (int i = 0; i < len; i++)
            if (data[i] == (byte)'>' && (i == 0 || data[i - 1] == (byte)'\n'))
                starts.Add(i);
        if (starts.Count == 0 || starts[0] != 0)
            starts.Insert(0, 0);            // tolerate data before the first header

        // Reverse-complement every record in place.  The sequence block is
        // reversed together with its interior line breaks (the final line
        // break stays where it is), so the input's wrapping is mirrored
        // exactly: the chunk that was last in the input becomes the short
        // first line of the output, the next-to-last chunk the second, ...
        for (int r = 0; r < starts.Count; r++)
        {
            int rs = starts[r];
            int re = r + 1 < starts.Count ? starts[r + 1] : len;
            if (rs >= re) continue;

            int seqStart = rs;
            if (data[rs] == (byte)'>')
            {
                int nl = rs;
                while (nl < re && data[nl] != (byte)'\n') nl++;
                seqStart = nl < re ? nl + 1 : re;
            }

            int t = re;
            while (t > seqStart && data[t - 1] == (byte)'\n') t--;

            int i = seqStart;
            int j = t - 1;
            while (i < j)
            {
                byte b = data[i];
                data[i] = comp[data[j]];
                data[j] = comp[b];
                i++; j--;
            }
            if (i == j)
                data[i] = comp[data[i]];
        }

        // The buffer now is the answer; ship it out in one go.
        Stream outp = Console.OpenStandardOutput();
        outp.Write(data, 0, len);
        outp.Flush();
    }
}
