void ProcessRecord(byte[] d, int rs, int re, byte[] comp) {
    int seqStart = rs;
    if (d[rs] == (byte)'>') {
        int nl = rs;
        while (nl < re && d[nl] != (byte)'\n') nl++;
        seqStart = nl + 1;  // if nl == re, seqStart = re + 1 > re — careful!
        if (nl >= re) seqStart = re;  // header with no trailing newline (EOF)
    }
    int t = re;
    while (t > seqStart && d[t-1] == (byte)'\n') t--;
    int i = seqStart, j = t - 1;
    while (i < j) {
        byte b = d[i];
        d[i] = comp[d[j]];
        d[j] = comp[b];
        i++; j--;
    }
    if (i == j) d[i] = comp[d[i]];
}
```

