using System;
using System.Collections.Generic;
using System.IO;

internal static class Program
{
    private static void Main(string[] args)
    {
        // The harness always passes N as the first command-line argument.
        // It does not change this task (the data comes from stdin), but parse it.
        if (args != null && args.Length > 0)
        {
            int ignored;
            int.TryParse(args[0], out ignored);
        }

        // IUPAC complement table; every other byte maps to itself
        // (so newlines and any unexpected characters pass through untouched).
        byte[] comp = new byte[256];
        for (int i = 0; i < 256; i++) comp[i] = (byte)i;
        comp['A'] = (byte)'T'; comp['T'] = (byte)'A';
        comp['C'] = (byte)'G'; comp['G'] = (byte)'C';
        comp['U'] = (byte)'A';
        comp['R'] = (byte)'Y'; comp['Y'] = (byte)'R';
        comp['K'] = (byte)'M'; comp['M'] = (byte)'K';
        comp['B'] = (byte)'V'; comp['V'] = (byte)'B';
        comp['D'] = (byte)'H'; comp['H'] = (byte)'D';
        comp['S'] = (byte)'S'; comp['W'] = (byte)'W'; comp['N'] = (byte)'N';
        comp['a'] = (byte)'t'; comp['t'] = (byte)'a';
        comp['c'] = (byte)'g'; comp['g'] = (byte)'c';
        comp['u'] = (byte)'a';
        comp['r'] = (byte)'y'; comp['y'] = (byte)'r';
        comp['k'] = (byte)'m'; comp['m'] = (byte)'k';
        comp['b'] = (byte)'v'; comp['v'] = (byte)'b';
        comp['d'] = (byte)'h'; comp['h'] = (byte)'d';
        comp['s'] = (byte)'s'; comp['w'] = (byte)'w'; comp['n'] = (byte)'n';

        // Read all of stdin (dropping carriage returns so line handling is uniform).
        Stream inp = Console.OpenStandardInput();
        MemoryStream ms = new MemoryStream(1 << 20);
        byte[] buf = new byte[1 << 16];
        int got;
        while ((got = inp.Read(buf, 0, buf.Length)) > 0)
        {
            int w = 0;
            for (int i = 0; i < got; i++)
                if (buf[i] != 13) buf[w++] = buf[i];
            ms.Write(buf, 0, w);
        }
        byte[] data = ms.GetBuffer();
        int len = (int)ms.Length;

        // Locate the start of every record: a '>' at the beginning of a line.
        List<int> starts = new List<int>();
        for (int i = 0; i < len; i++)
            if (data[i] == (byte)'>' && (i == 0 || data[i - 1] == (byte)'\n'))
                starts.Add(i);
        if (starts.Count == 0 || starts[0] != 0) starts.Insert(0, 0);

        // Reverse-complement each record in place. Reversing the wrapped block
        // (with its line breaks, minus the final one) mirrors the line wrapping,
        // which is exactly what "preserve the line-wrapping" requires.
        for (int r = 0; r < starts.Count; r++)
        {
            int rs = starts[r];
            int re = r + 1 < starts.Count ? starts[r + 1] : len;
            if (rs >= re) continue;

            int seqStart = rs;
            if (data[rs] == (byte)'>')
            {
                int nl = rs;
                while (nl < re && data[nl] != (byte)'\n') nl++;
                seqStart = nl < re ? nl + 1 : re;
            }

            int t = re;
            while (t > seqStart && data[t - 1] == (byte)'\n') t--;

            int i = seqStart;
            int j = t - 1;
            while (i < j)
            {
                byte b = data[i];
                data[i] = comp[data[j]];
                data[j] = comp[b];
                i++; j--;
            }
            if (i == j) data[i] = comp[data[i]];
        }

        Stream outp = Console.OpenStandardOutput();
        outp.Write(data, 0, len);
        outp.Flush();
    }
}
