The standard reference implementation (from benchmarks game, e.g., the C or Java version):

```c
int fannkuch(int n) {
   int* perm  = (int*) malloc(n * sizeof(int));
   int* perm1 = (int*) malloc(n * sizeof(int));
   int* count = (int*) malloc(n * sizeof(int));

   int flips;
   int flipsMax;
   int r;
   int i, k, l;
   int nperm;
   int checksum;

   unsigned int* perm_temp;

   for (i=0; i<n; i++) perm1[i] = i;

   r = n;
   flipsMax = 0;
   nperm = 0;
   checksum = 0;

   while (1) {
      while (r != 1){
         count[r-1] = r;
         r--;
      }

      // are all permutations done?
      if (perm1[0] != 0){
         for (i=0; i<n; i++) perm[i] = perm1[i];

         flips = 0;
         k = perm1[0];
         do {
            i = 1;
            do {
               perm_temp = perm[i];
               perm[i] = perm[i-1];
               perm[i-1] = perm_temp;
               i++;
            } while (i < k);
            k--;
            flips++;
         } while (k > 0);

         if (flipsMax == 0 || flipsMax < flips) {
            flipsMax = flips;
         }

         nperm++;
         if (nperm % 2 == 1) {
            checksum += flips;
         } else {
            checksum -= flips;
         }
      }

      while (1) {
         if (r == n) {
            printf("%d\nPfannkuchen(%d) = %d\n", checksum, n, flipsMax);
            return checksum;
         }

         // rotate permutation
         perm0 = perm1[0];
         i = 0;
         while (i < r) {
            l = i+1;
            perm1[i] = perm1[l];
            i++;
         }
         perm1[r] = perm0;
         r--;

         if (count[r] > 0) break;
      }
   }
}
```

