use std::env;

fn fannkuch(n: i32) -> (i32, i32) {
    unsafe {
        let n = n as usize;
        let mut perm1: Vec<i32> = (0..n as i32).collect();
        let mut perm: Vec<i32> = vec![0; n];
        let mut count: Vec<i32> = vec![0; n];
        let mut flips: i32;
        let mut flipsmax: i32 = 0;
        let mut checksum: i64 = 0;
        let mut nperm: i64 = 0;
        let mut r: usize = n;

        loop {
            while r != 1 {
                count[r - 1] = r as i32;
                r -= 1;
            }
            if perm1[0] != 0 {
                perm.copy_from_slice(&perm1);
                flips = 0;
                let mut k = perm1[0];
                while k != 0 {
                    let mut i = 0;
                    let mut j = k;
                    while i < j {
                        let t = perm[i as usize];
                        perm[i as usize] = perm[j as usize];
                        perm[j as usize] = t;
                        i += 1;
                        j -= 1;
                    }
                    k = perm[0];
                    flips += 1;
                }
                if flipsmax < flips {
                    flipsmax = flips;
                }
                nperm += 1;
                if nperm % 2 == 1 {
                    checksum += flips as i64;
                } else {
                    checksum -= flips as i64;
                }
            }
            loop {
                if r == n {
                    println!("{}", checksum);
                    println!("Pfannkuchen({}) = {}", n, flipsmax);
                    return (checksum as i32, flipsmax);
                }
                let perm0 = perm1[0];
                for i in 0..r {
                    perm1[i] = perm1[i + 1];
                }
                perm1[r] = perm0;
                r -= 1;
                if count[r] > 0 {
                    break;
                }
            }
        }
    }
}
```

